def inject(
    self,
    trajectory: List[Dict[str, Any]],
    env_idx: int,
    step_idx: int,
    config: Dict[str, Any],
) -> List[Dict[str, Any]]:
    traj = copy.deepcopy(trajectory)
    mask_type = config.get("mask_type", "generic")
    mask_prob = config.get("mask_probability", 0.3)

    for step in traj:
        if random.random() < mask_prob:
            if mask_type == "empty":
                step["text_obs"] = ""
            else:
                step["text_obs"] = GENERIC_OBS

    return traj
